import csv, datetime as dt, statistics
DATA="/home/shadeform/gpumode/autocuda"; TAG="2026-06-22-09-10-03-qr_v2"
def parse(ts): return dt.datetime.fromisoformat(ts)
workers=[0,1,2,3]; wrows={}
for w in workers:
    rows=[]
    with open(f"{DATA}/{TAG}-optimize-tree-worker-{w}-log.csv") as f:
        r=csv.reader(f); next(r)
        for line in r:
            if len(line)<6: continue
            try: ts=parse(line[0])
            except: continue
            rows.append({'ts':ts,'brief_id':line[2],'status':line[5] if len(line)>5 else ''})
    wrows[w]=rows
mrows=[]
with open(f"{DATA}/{TAG}-optimize-tree-manager-log.csv") as f:
    r=csv.reader(f); next(r)
    for line in r:
        if len(line)<6: continue
        try: ts=parse(line[0])
        except: continue
        mrows.append({'ts':ts,'agent_id':line[1],'brief_id':line[2]})

# Interpretation A: manager brief row -> matching worker brief_start (same brief_id, ts>=)
gapsA=[]; missA=0
for m in mrows:
    try: a=int(m['agent_id'])
    except: continue
    if a not in workers: continue
    cand=[r for r in wrows[a] if r['status']=='brief_start' and r['brief_id']==m['brief_id'] and r['ts']>=m['ts']]
    if cand:
        gapsA.append((min(c['ts'] for c in cand)-m['ts']).total_seconds())
    else:
        missA+=1
print("A) manager-row -> matching brief_start:")
if gapsA:
    gs=sorted(gapsA)
    print(f"   n={len(gapsA)} miss={missA} median={statistics.median(gapsA):.1f}s p95={gs[int(0.95*len(gs))-1]:.1f}s max={max(gapsA):.1f}s min={min(gapsA):.1f}s")
    print(f"   >5min: {sum(1 for g in gapsA if g>300)}  >1min: {sum(1 for g in gapsA if g>60)}")

# Interpretation B: worker brief_start -> first non-lifecycle row of SAME brief after it (time-to-first-trial)
LIFE={'brief_start','brief_stop','baseline','status',''}
gapsB=[]
for w in workers:
    rows=sorted(wrows[w], key=lambda r:r['ts'])
    for i,r in enumerate(rows):
        if r['status']=='brief_start':
            # next non-lifecycle row
            for r2 in rows[i+1:]:
                if r2['status']=='brief_start': break  # next brief began w/o any trial
                if r2['status'] not in LIFE:
                    gapsB.append((r2['ts']-r['ts']).total_seconds()); break
print("\nB) brief_start -> first trial activity (time-to-first-trial):")
if gapsB:
    gs=sorted(gapsB)
    print(f"   n={len(gapsB)} median={statistics.median(gapsB):.1f}s p95={gs[int(0.95*len(gs))-1]:.1f}s max={max(gapsB):.1f}s")
    print(f"   >5min: {sum(1 for g in gapsB if g>300)}")

# Distribution of A in minutes
import collections
if gapsA:
    buckets=collections.Counter()
    for g in gapsA:
        if g<=60: buckets['<=1min']+=1
        elif g<=300: buckets['1-5min']+=1
        elif g<=900: buckets['5-15min']+=1
        else: buckets['>15min']+=1
    print("\nA distribution:", dict(buckets))
